 </head>
 <body>
   <div id="root"></div>

   <script>
     const image = {
       title: "Nebula Study 08",
       collection: "Personal library",
       dimensions: "3840 x 2160",
       uploaded: "May 6, 2026",
       fileType: "PNG"
     };

     const ImagePreview = ({ title }) => `
       <section class="image-frame" aria-label="Preview of ${title}">
         <span class="image-label">Image preview</span>
       </section>
     `;

     const ImageDetails = ({ collection, dimensions, uploaded, fileType, title }) => `
       <aside class="details">
         <div>
           <p class="eyebrow">${collection}</p>
           <h1>${title}</h1>
           <p class="description">
             A high-resolution artwork saved in your image library. Use the delete action below
             to remove this image permanently after confirmation.
           </p>
         </div>

         <dl class="meta-grid">
           <div class="meta-item">
             <dt>Dimensions</dt>
             <dd>${dimensions}</dd>
           </div>
           <div class="meta-item">
             <dt>Uploaded</dt>
             <dd>${uploaded}</dd>
           </div>
           <div class="meta-item">
             <dt>Format</dt>
             <dd>${fileType}</dd>
           </div>
           <div class="meta-item">
             <dt>Status</dt>
             <dd>In library</dd>
           </div>
         </dl>

         <div class="actions">
           <button class="button button-secondary" type="button">Download</button>
           <button class="button button-danger trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
             Delete image
           </button>
         </div>
       </aside>
     `;

     const DeleteDialog = ({ title }) => `
       <div class="modal-backdrop" data-modal-backdrop>
         <section
           class="modal-dialog"
           id="delete-dialog"
           role="dialog"
           aria-modal="true"
           aria-labelledby="dialog-title"
           aria-describedby="dialog-description"
         >
           <div class="modal-content">
             <div class="warning-icon" aria-hidden="true">!</div>
             <h2 id="dialog-title">Delete this image?</h2>
             <p id="dialog-description">
               This will permanently remove <strong>${title}</strong> from your library.
               This action cannot be undone.
             </p>
             <div class="modal-actions">
               <button class="button button-ghost" type="button" data-close-modal>Cancel</button>
               <button class="button button-danger" type="button" data-confirm-delete>Delete permanently</button>
             </div>
           </div>
         </section>
       </div>
     `;

     const ImagePreviewPage = (props) => `
       <main class="app-shell">
         <article class="preview-card">
           ${ImagePreview(props)}
           ${ImageDetails(props)}
         </article>
       </main>
       ${DeleteDialog(props)}
     `;

     const root = document.querySelector("#root");
     root.innerHTML = ImagePreviewPage(image);

     const trigger = document.querySelector(".trigger");
     const backdrop = document.querySelector("[data-modal-backdrop]");
     const dialog = document.querySelector("#delete-dialog");
     const closeButtons = document.querySelectorAll("[data-close-modal], [data-confirm-delete]");
     let previousFocus = null;

     const openDialog = () => {
       previousFocus = document.activeElement;
       backdrop.classList.add("is-open");
       trigger.setAttribute("aria-expanded", "true");
       dialog.querySelector("button").focus();
     };

     const closeDialog = () => {
       backdrop.classList.remove("is-open");
       trigger.setAttribute("aria-expanded", "false");

       if (previousFocus) {
         previousFocus.focus();
       }
     };

     trigger.setAttribute("aria-expanded", "false");
     trigger.addEventListener("click", openDialog);

     closeButtons.forEach((button) => {
       button.addEventListener("click", closeDialog);
     });

     backdrop.addEventListener("click", (event) => {
       if (event.target === backdrop) {
         closeDialog();
       }
     });

     document.addEventListener("keydown", (event) => {
       if (event.key === "Escape" && backdrop.classList.contains("is-open")) {
         closeDialog();
       }
     });
   </script>
 </body>
 </html>

